schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/google-analytics.json",
  "title": "Google Analytics 4 property config",
  "type": "object",
  "required": ["property_id", "site_domain", "data_streams", "enhanced_measurement", "custom_dimensions", "events", "key_events", "purchase", "consent", "bigquery_export", "data_retention_months", "measurement_protocol", "traffic_filters"],
  "additionalProperties": false,
  "definitions": {
    "host": {"type": "string", "pattern": "^[a-z0-9.-]+\\.[a-z]{2,}$"},
    "snake": {"type": "string", "pattern": "^[a-z][a-z0-9_]{0,39}$"},
    "count": {"type": "integer", "minimum": 0}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "property_id": {"type": "string", "pattern": "^[0-9]{6,12}$"},
    "site_domain": {"$ref": "#/definitions/host"},
    "data_streams": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "type", "measurement_id", "spa", "manual_page_view", "send_page_view"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "type": {"type": "string", "enum": ["web", "ios", "android"]},
          "measurement_id": {"type": "string", "pattern": "^G-[A-Z0-9]{6,12}$"},
          "spa": {"type": "boolean"},
          "manual_page_view": {"type": "boolean"},
          "send_page_view": {"type": "boolean"}
        },
        "if": {"properties": {"manual_page_view": {"const": true}}},
        "then": {"properties": {"send_page_view": {"const": false}}},
        "else": {"properties": {"send_page_view": {"const": true}}}
      }
    },
    "enhanced_measurement": {
      "type": "object",
      "required": ["page_views", "history_change_page_view", "scrolls", "outbound_clicks", "site_search", "video_engagement", "file_downloads", "form_interactions"],
      "additionalProperties": false,
      "properties": {
        "page_views": {"type": "boolean"},
        "history_change_page_view": {"type": "boolean"},
        "scrolls": {"type": "boolean"},
        "outbound_clicks": {"type": "boolean"},
        "site_search": {"type": "boolean"},
        "video_engagement": {"type": "boolean"},
        "file_downloads": {"type": "boolean"},
        "form_interactions": {"type": "boolean"}
      }
    },
    "custom_dimensions": {
      "type": "object",
      "required": ["limits", "registered", "used"],
      "additionalProperties": false,
      "properties": {
        "limits": {
          "type": "object",
          "required": ["event", "user", "item", "metrics"],
          "additionalProperties": false,
          "properties": {"event": {"type": "integer", "minimum": 1}, "user": {"type": "integer", "minimum": 1}, "item": {"type": "integer", "minimum": 1}, "metrics": {"type": "integer", "minimum": 1}}
        },
        "registered": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["name", "parameter", "scope", "kind", "registered_before_first_send"],
            "additionalProperties": false,
            "properties": {
              "name": {"type": "string", "minLength": 2},
              "parameter": {"$ref": "#/definitions/snake"},
              "scope": {"type": "string", "enum": ["event", "user", "item"]},
              "kind": {"type": "string", "enum": ["dimension", "metric"]},
              "registered_before_first_send": {"const": true}
            }
          }
        },
        "used": {
          "type": "object",
          "required": ["event", "user", "item", "metrics"],
          "additionalProperties": false,
          "properties": {"event": {"$ref": "#/definitions/count"}, "user": {"$ref": "#/definitions/count"}, "item": {"$ref": "#/definitions/count"}, "metrics": {"$ref": "#/definitions/count"}}
        }
      }
    },
    "events": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/definitions/snake"}},
    "key_events": {
      "type": "array",
      "minItems": 1,
      "maxItems": 30,
      "items": {
        "type": "object",
        "required": ["event_name", "counting"],
        "additionalProperties": false,
        "properties": {
          "event_name": {"$ref": "#/definitions/snake"},
          "counting": {"type": "string", "enum": ["once_per_event", "once_per_session"]}
        }
      }
    },
    "purchase": {
      "type": "object",
      "required": ["enabled"],
      "properties": {"enabled": {"type": "boolean"}},
      "if": {"properties": {"enabled": {"const": true}}},
      "then": {
        "required": ["required_parameters", "transaction_id_source", "stable_across_retries"],
        "additionalProperties": false,
        "properties": {
          "enabled": {"const": true},
          "required_parameters": {
            "type": "array",
            "minItems": 4,
            "items": {"$ref": "#/definitions/snake"},
            "allOf": [{"contains": {"const": "transaction_id"}}, {"contains": {"const": "value"}}, {"contains": {"const": "currency"}}, {"contains": {"const": "items"}}]
          },
          "transaction_id_source": {"const": "order_id"},
          "stable_across_retries": {"const": true}
        }
      },
      "else": {"additionalProperties": false, "properties": {"enabled": {"const": false}}}
    },
    "consent": {
      "type": "object",
      "required": ["in_scope"],
      "properties": {"in_scope": {"type": "boolean"}},
      "if": {"properties": {"in_scope": {"const": true}}},
      "then": {
        "required": ["implementation", "defaults_before_config", "signals", "regions", "update_on_choice"],
        "additionalProperties": false,
        "properties": {
          "in_scope": {"const": true},
          "implementation": {"type": "string", "enum": ["basic", "advanced"]},
          "defaults_before_config": {"const": true},
          "signals": {
            "type": "array",
            "minItems": 4,
            "items": {"type": "string", "enum": ["ad_storage", "analytics_storage", "ad_user_data", "ad_personalization"]},
            "allOf": [{"contains": {"const": "ad_storage"}}, {"contains": {"const": "analytics_storage"}}, {"contains": {"const": "ad_user_data"}}, {"contains": {"const": "ad_personalization"}}]
          },
          "regions": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^[A-Z]{2}(-[A-Z0-9]{1,3})?$"}},
          "update_on_choice": {"const": true}
        }
      },
      "else": {"additionalProperties": false, "properties": {"in_scope": {"const": false}}}
    },
    "bigquery_export": {
      "type": "object",
      "required": ["linked", "linked_before_launch", "linked_at", "project", "dataset_location", "daily", "streaming", "sampling_threshold_events", "decision_reports_source"],
      "additionalProperties": false,
      "properties": {
        "linked": {"const": true},
        "linked_before_launch": {"const": true},
        "linked_at": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
        "project": {"type": "string", "minLength": 3},
        "dataset_location": {"type": "string", "minLength": 2},
        "daily": {"const": true},
        "streaming": {"type": "boolean"},
        "sampling_threshold_events": {"type": "integer", "minimum": 1},
        "decision_reports_source": {"const": "bigquery"}
      }
    },
    "data_retention_months": {"const": 14},
    "measurement_protocol": {
      "type": "object",
      "required": ["used"],
      "properties": {"used": {"type": "boolean"}},
      "if": {"properties": {"used": {"const": true}}},
      "then": {
        "required": ["client_id_source", "session_id_included", "engagement_time_msec_included", "api_secret_storage", "fresh_client_id"],
        "additionalProperties": false,
        "properties": {
          "used": {"const": true},
          "client_id_source": {"const": "_ga cookie"},
          "session_id_included": {"const": true},
          "engagement_time_msec_included": {"const": true},
          "api_secret_storage": {"const": "server_only"},
          "fresh_client_id": {"const": false}
        }
      },
      "else": {"additionalProperties": false, "properties": {"used": {"const": false}}}
    },
    "traffic_filters": {
      "type": "object",
      "required": ["internal", "checkout_and_auth_domains", "unwanted_referrals", "cross_domain"],
      "additionalProperties": false,
      "properties": {
        "internal": {
          "type": "object",
          "required": ["ip_rules", "state"],
          "additionalProperties": false,
          "properties": {
            "ip_rules": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^[0-9]{1,3}(\\.[0-9]{1,3}){3}(/[0-9]{1,2})?$"}},
            "state": {"const": "active"}
          }
        },
        "checkout_and_auth_domains": {"type": "array", "items": {"$ref": "#/definitions/host"}},
        "unwanted_referrals": {"type": "array", "items": {"$ref": "#/definitions/host"}},
        "cross_domain": {"type": "array", "items": {"$ref": "#/definitions/host"}}
      }
    }
  }
}

output-contract.example:
{
  "property_id": "123456789",
  "site_domain": "example.com",
  "data_streams": [
    {"name": "example.com web", "type": "web", "measurement_id": "G-AB12CD34EF", "spa": true, "manual_page_view": true, "send_page_view": false}
  ],
  "enhanced_measurement": {"page_views": true, "history_change_page_view": false, "scrolls": true, "outbound_clicks": true, "site_search": false, "video_engagement": false, "file_downloads": true, "form_interactions": false},
  "custom_dimensions": {
    "limits": {"event": 50, "user": 25, "item": 10, "metrics": 50},
    "registered": [
      {"name": "Plan tier", "parameter": "plan_tier", "scope": "user", "kind": "dimension", "registered_before_first_send": true},
      {"name": "Funnel name", "parameter": "funnel_name", "scope": "event", "kind": "dimension", "registered_before_first_send": true},
      {"name": "Step number", "parameter": "step_number", "scope": "event", "kind": "dimension", "registered_before_first_send": true},
      {"name": "Seats", "parameter": "seats", "scope": "event", "kind": "metric", "registered_before_first_send": true}
    ],
    "used": {"event": 2, "user": 1, "item": 0, "metrics": 1}
  },
  "events": ["page_view", "sign_up", "generate_lead", "purchase", "funnel_step", "login"],
  "key_events": [
    {"event_name": "purchase", "counting": "once_per_event"},
    {"event_name": "generate_lead", "counting": "once_per_session"},
    {"event_name": "sign_up", "counting": "once_per_event"}
  ],
  "purchase": {"enabled": true, "required_parameters": ["transaction_id", "value", "currency", "items"], "transaction_id_source": "order_id", "stable_across_retries": true},
  "consent": {"in_scope": true, "implementation": "advanced", "defaults_before_config": true, "signals": ["ad_storage", "analytics_storage", "ad_user_data", "ad_personalization"], "regions": ["EU", "GB", "CH"], "update_on_choice": true},
  "bigquery_export": {"linked": true, "linked_before_launch": true, "linked_at": "2026-04-20", "project": "acme-analytics-prod", "dataset_location": "EU", "daily": true, "streaming": false, "sampling_threshold_events": 10000000, "decision_reports_source": "bigquery"},
  "data_retention_months": 14,
  "measurement_protocol": {"used": true, "client_id_source": "_ga cookie", "session_id_included": true, "engagement_time_msec_included": true, "api_secret_storage": "server_only", "fresh_client_id": false},
  "traffic_filters": {
    "internal": {"ip_rules": ["203.0.113.0/24", "198.51.100.17"], "state": "active"},
    "checkout_and_auth_domains": ["paypal.com", "checkout.stripe.com", "auth.example.com"],
    "unwanted_referrals": ["paypal.com", "checkout.stripe.com", "auth.example.com"],
    "cross_domain": ["example.com", "shop.example.com"]
  }
}

